function parseJson(value) {
  if (typeof value !== "string") {
    return value;
  }

  let text = value.trim();

  // Remove Markdown code fences if present
  text = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  // Parse JSON, including JSON strings containing JSON
  let parsed = JSON.parse(text);

  if (typeof parsed === "string") {
    parsed = JSON.parse(parsed);
  }

  return parsed;
}

function titleCase(value) {
  if (!value) return "Unknown";

  return String(value)
    .trim()
    .toLowerCase()
    .replace(/\b[a-z]/g, char => char.toUpperCase());
}

function normalizeDate(value) {
  if (!value) return "";

  const text = String(value).trim();

  // Already YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return text;
  }

  // Handle M/D/YYYY or MM/DD/YYYY
  const match = text.match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
  );

  if (match) {
    const [, month, day, year] = match;

    return `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
  }

  return "";
}

function cleanStudent(student) {
  const name = String(student.name ?? "").trim();

  const email = String(student.email ?? "").trim();

  const phoneDigits = String(student.phone ?? "")
    .replace(/\D/g, "");

  const courseValue = String(student.course ?? "")
    .trim()
    .toLowerCase();

  const allowedCourses = {
    "python": "Python",
    "machine learning": "Machine Learning",
    "data science": "Data Science"
  };

  const feeValue = student.fee_paid;

  const feeNumber =
    feeValue === null ||
    feeValue === undefined ||
    String(feeValue).trim() === ""
      ? 0
      : Number(feeValue);

  const city = String(student.city ?? "").trim();

  return {
    Student_id: student.Student_id ?? student.student_id ?? "",
    name: name ? titleCase(name) : "Unknown",
    email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
      ? email
      : "INVALID_EMAIL",
    phone: phoneDigits.length < 10
      ? "MISSING"
      : phoneDigits,
    course: allowedCourses[courseValue] ?? "INVALID_COURSE",
    fee_paid: Number.isFinite(feeNumber) && feeNumber > 0,
    city: city ? titleCase(city) : "Unknown",
    enrolled_date: normalizeDate(
      student.enrolled_date ?? student.Enrolled_Date
    )
  };
}

return $input.all().map((item, index) => {
  try {
    // Adjust these field names to match your Basic LLM Chain output.
    const output =
      item.json.text ??
      item.json.output ??
      item.json.response ??
      item.json;

    const student = parseJson(output);

    if (!student || typeof student !== "object" || Array.isArray(student)) {
      throw new Error("Expected a JSON object");
    }

    return {
      json: cleanStudent(student),
      pairedItem: { item: index }
    };
  } catch (error) {
    return {
      json: {
        error: "Failed to parse or clean student record",
        details: error.message,
        original: item.json
      },
      pairedItem: { item: index }
    };
  }
});
